const express = require('express');
const { db } = require('../db');
const { cronSchedules } = require('../schema');
const { and, eq } = require('drizzle-orm');
const { verifyEmployeeToken } = require('../auth');

const router = express.Router();

router.patch('/api/cron/payroll-reports/:scheduleId/recipients', verifyEmployeeToken, async (req, res) => {
  const { scheduleId } = req.params;
  const { recipientEmails } = req.body;

  if (!req.employee.roles?.includes('PAYROLL_ADMIN')) {
    return res.status(403).json({ error: 'Forbidden: requires PAYROLL_ADMIN role' });
  }

  const updated = await db.update(cronSchedules)
    .set({ targetEmails: recipientEmails })
    .where(and(eq(cronSchedules.id, scheduleId), eq(cronSchedules.departmentId, req.employee.departmentId)))
    .returning();

  if (!updated.length) return res.status(404).json({ error: 'Schedule not found or unauthorized' });
  res.json({ success: true, updatedSchedule: updated[0] });
});
